@@ -274,7 +274,8 @@ class InlineVariables implements CompilerPass {
       // the next pass.)
       if (
           !staleVars.contains(v) && referenceInfo.isWellDefined() &&
-          referenceInfo.isAssignedOnceInLifetime()) {
+          referenceInfo.isAssignedOnceInLifetime() &&
+          !isParameterAffectedByArgumentsModification(v)) {
         List<Reference> refs = referenceInfo.references;
         for (int i = 1 /* start from a read */; i < refs.size(); i++) {
           Node nameNode = refs.get(i).getNameNode();
@@ -296,6 +297,57 @@ class InlineVariables implements CompilerPass {
       }
     }

+    /**
+     * If v is a function parameter whose function's "arguments" object
+     * is modified, the value of v is not stable (writes to arguments[i]
+     * alias parameter i), so v is not safe to use as an alias source.
+     */
+    private boolean isParameterAffectedByArgumentsModification(Var v) {
+      Node parent = v.getParentNode();
+      if (parent == null || parent.getType() != Token.LP) {
+        return false;
+      }
+      Node function = parent.getParent();
+      if (function == null || function.getType() != Token.FUNCTION) {
+        return false;
+      }
+      return hasArgumentsAssignment(function.getLastChild());
+    }
+
+    /**
+     * Returns true if the subtree rooted at n contains an assignment whose
+     * left-hand side is a property/element access on the local "arguments"
+     * object. Does not descend into nested function bodies, since those have
+     * their own "arguments".
+     */
+    private boolean hasArgumentsAssignment(Node n) {
+      if (n == null) {
+        return false;
+      }
+      if (NodeUtil.isAssignmentOp(n)) {
+        Node lhs = n.getFirstChild();
+        if (lhs != null
+            && (lhs.getType() == Token.GETELEM
+                || lhs.getType() == Token.GETPROP)) {
+          Node target = lhs.getFirstChild();
+          if (target != null
+              && target.getType() == Token.NAME
+              && "arguments".equals(target.getString())) {
+            return true;
+          }
+        }
+      }
+      for (Node c = n.getFirstChild(); c != null; c = c.getNext()) {
+        if (c.getType() == Token.FUNCTION) {
+          continue;
+        }
+        if (hasArgumentsAssignment(c)) {
+          return true;
+        }
+      }
+      return false;
+    }
+
